var EXTRA=[{"dot": "gray", "j": "Arthrosc Tech", "h": "Rotula: ricostruzione di MPFL e legamento quadricipite-femorale in un gesto, con allograft", "v": "Nota tecnica senza pazienti: descrive il gesto con tensionamento dinamico, non ne misura l'esito; l'abstract non nomina il tipo di fissazione.", "pmid": "42960305", "doi": "10.1002/atn2.70386", "temi": ["MPFL", "instabilità rotulea", "nota tecnica"]}, {"dot": "gray", "j": "Eur J Orthop Surg Traumatol", "h": "Osteotomia di slope con il LCA: letteratura in crescita, ma per lo più retrospettiva o biomeccanica", "v": "Analisi bibliometrica: mappa chi pubblica e non quanto la tecnica funzioni; gli autori chiedono indicazioni standardizzate e soglie di slope validate.", "pmid": "42944805", "doi": "10.1007/s00590-026-05019-y", "temi": ["slope", "osteotomia", "LCA", "bibliometria"]}, {"dot": "gray", "j": "Knee Surg Relat Res", "h": "Osteotomia tibiale aperta: una correzione sufficiente protegge dal restringimento dello spazio mediale", "v": "Coorte retrospettiva con soglia ricavata dagli stessi dati; l'effetto è chiaro solo nei ginocchi senza artrosi radiografica e il follow-up è breve.", "pmid": "42958464", "doi": "10.1186/s43019-026-00338-0", "temi": ["osteotomia", "MPTA", "spazio articolare"]}, {"dot": "gray", "j": "Asia Pac J Sports Med Arthrosc Rehabil Technol", "h": "Osteotomia tibiale aperta: la stabilità dinamica migliora, e l'instabilità preoperatoria la predice", "v": "Retrospettivo, un solo gruppo e pochi ginocchi, senza confronto; la stabilità è misurata con radioscopia da stress in sala.", "pmid": "42960013", "doi": "10.1016/j.asmart.2026.10.001", "temi": ["osteotomia", "stabilità dinamica", "slope"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Angolo posterolaterale: ricostruzione con legamento artificiale a Y e un solo tunnel femorale", "v": "Nota tecnica senza pazienti: evita il prelievo di innesto, ma il lavoro non riporta esiti del legamento artificiale.", "pmid": "42959926", "doi": "10.1002/atn2.70333", "temi": ["angolo posterolaterale", "multilegamentose", "legamento artificiale"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Menisco laterale discoide: sutura all-inside con rilascio del cordone anteriore, conservando il menisco", "v": "Nota tecnica senza pazienti: gli autori escludono le lesioni estese con blocco, dove preferiscono la sutura inside-out.", "pmid": "42959339", "doi": "10.1002/atn2.70360", "temi": ["menisco discoide", "sutura all-inside", "menisco laterale"]}, {"dot": "gray", "j": "Arthrosc Sports Med Rehabil", "h": "Allotrapianto osteocondrale: i criteri di copertura delle assicurazioni americane poggiano su prove di livello basso", "v": "Analisi di politiche assicurative statunitensi: non riguarda l'efficacia dell'intervento e non è trasferibile al sistema svizzero.", "pmid": "42960286", "doi": "10.1002/ars2.70094", "temi": ["allotrapianto osteocondrale", "cartilagine", "assicurazioni"]}, {"dot": "gray", "j": "Front Bioeng Biotechnol", "h": "Legamenti sintetici in PET: la superficie funzionalizzata migliora l'integrazione, ma resta sotto il legamento nativo", "v": "Revisione sistematica con dati su animali e meccanici, senza esiti nel paziente; tra gli autori Tommaso Bonanzinga.", "pmid": "42952745", "doi": "10.3389/fbioe.2026.1916072", "temi": ["legamento artificiale", "LCA", "biomateriali"]}, {"dot": "gray", "j": "J Orthop Surg (Hong Kong)", "h": "Protesi totale: pianificazione con intelligenza artificiale e robot, dimensionamento femorale più accurato", "v": "Coorte retrospettiva con appaiamento su punteggio di propensione; l'esito principale è l'accuratezza della taglia, non la durata dell'impianto.", "pmid": "42961828", "doi": "10.1177/10225536261504098", "temi": ["protesi totale", "robotica", "pianificazione"]}, {"dot": "gray", "j": "J Exp Orthop", "h": "Lesione meniscale nei calciatori professionisti: il valore di mercato segue la carriera attesa", "v": "Coorte retrospettiva sui dati di Transfermarkt, un indicatore economico e non clinico; primo autore Riccardo D'Ambrosi.", "pmid": "42959839", "doi": "10.1002/jeo2.70968", "temi": ["menisco", "calcio professionistico", "ritorno allo sport"]}];
var SCOPERTE=[{"t": "Un legamento artificiale intrecciato in seta e fibra di vetro: nel coniglio il recupero motorio è rapido", "v": "Ingegneria dei materiali da gruppi cinesi: il legamento imita la curva a J del legamento nativo e favorisce l'integrazione con l'osso. È solo animale: vale la deviazione per vedere dove si cerca l'alternativa all'innesto, non per cambiare qualcosa in sala.", "pmid": "42958727", "doi": "10.1002/advs.78414", "temi": ["bioingegneria", "legamento artificiale", "LCA", "Cina"]}, {"t": "Prevedere la lesione meniscale degenerativa prima che si veda: radiomica su risonanza in una coorte longitudinale", "v": "Un modello integra i segnali di sei strutture del ginocchio e stima il rischio a quattro anni; migliora anche l'accordo di lettura fra chirurghi in formazione. Vale la deviazione come esempio di intelligenza artificiale applicata al menisco: è un modello di rischio, non uno strumento per decidere un intervento.", "pmid": "42960748", "doi": "10.1002/advs.78506", "temi": ["intelligenza artificiale", "radiomica", "menisco", "risonanza"]}, {"t": "Riassumere una consensus con l'intelligenza artificiale: i modelli linguistici reggono il confronto con gli esperti?", "v": "Studio esplorativo su due parti della consensus ESSKA-AOSSM-AASPT sulla riabilitazione del menisco, valutato in cieco da fisioterapisti: il titolo riporta nessuna differenza significativa, che in uno studio esplorativo non prova equivalenza. Vale la deviazione per capire quanto fidarsi dei riassunti automatici.", "pmid": "42953767", "doi": "10.1002/jeo2.70964", "temi": ["intelligenza artificiale", "consensus", "riabilitazione meniscale"]}];
var SOC={"2": {"video": "Quando il menisco interno si stacca dalla sua radice si può ricucire. Una coorte di 91 pazienti mostra che chi aveva già una piccola frattura da insufficienza dell'osso sotto la cartilagine, visibile alla risonanza, ha risultati diversi. Con la frattura ha avuto un miglioramento clinicamente importante il 38,2% dei pazienti, contro l'80,7% di chi non l'aveva. I nuovi interventi sono stati il 20,6% contro il 5,3% e l'artrosi alla radiografia era più avanzata dopo circa tre anni.\n\nIl limite: studio retrospettivo, senza assegnazione casuale; mostra un'associazione e non dice se la frattura causi l'esito. Il tipo di sutura non è riportato.\nFonte: PubMed, PMID 42958723.", "linkedin": "Radice mediale e SIFK (Arthroscopy, 2026): coorte retrospettiva, 91 pazienti operati di sutura della radice posteriore, follow-up medio 38,3 mesi; 34 (37,4%) con frattura da insufficienza subcondrale alla RM. Con SIFK: KOOS-JR raggiunge la differenza minima rilevante nel 38,2% contro l'80,7% (p < 0,001); reinterventi 20,6% contro 5,3% (differenza di rischio 15,3 punti, IC 95% 1,6-31,9); Kellgren-Lawrence mediano 3,0 contro 2,0 (p = 0,013).\n\nIl limite: retrospettivo, reinterventi in pochi pazienti (7 e 3, dedotti dalle percentuali), tecnica di sutura e centralizzazione non riportate. Solo abstract.\nFonte: PubMed, PMID 42958723.", "instagram": "Menisco interno ricucito alla radice: conta una piccola frattura dell'osso sotto la cartilagine.\n\nIn 91 pazienti chi l'aveva ha avuto più nuovi interventi e meno miglioramento. Studio retrospettivo, mostra un'associazione.\nFonte: PubMed, PMID 42958723.", "pazienti": "Il menisco interno può staccarsi dalla sua radice posteriore e in alcuni casi si ricuce. Uno studio su 91 persone ha guardato se una piccola frattura dell'osso sotto la cartilagine, vista alla risonanza, cambia il risultato. Chi aveva quella frattura ha avuto più spesso un miglioramento limitato e più spesso una nuova operazione, e la sua artrosi alla radiografia era più avanzata dopo circa tre anni.\n\nLo studio guarda indietro nel tempo e non può dire che la frattura sia la causa. Per ogni caso decide il chirurgo con il paziente.\nFonte: PubMed, PMID 42958723."}};
var SOCV={"2": {"video": {"chir": ["Radice del menisco mediale e frattura da insufficienza subcondrale (Arthroscopy, 2026): coorte retrospettiva di 91 pazienti con sutura della radice posteriore e follow-up medio di 38 mesi, 34 con frattura alla RM.", "Con la frattura il KOOS-JR raggiunge la differenza minima rilevante nel 38,2% contro l'80,7% (p < 0,001); reinterventi 20,6% contro 5,3% (differenza di rischio 15,3 punti, IC 95% 1,6-31,9); Kellgren-Lawrence mediano 3,0 contro 2,0.", "Il limite: retrospettivo e non randomizzato, tecnica di sutura non riportata, intervallo dei reinterventi molto largo. Solo abstract.\nFonte: PubMed, PMID 42958723."], "misto": ["Quando il menisco interno si stacca dalla sua radice si può ricucire. Una coorte di 91 pazienti mostra che chi aveva già una piccola frattura da insufficienza dell'osso sotto la cartilagine, visibile alla risonanza, ha risultati diversi.", "Con la frattura ha avuto un miglioramento clinicamente importante il 38,2% dei pazienti, contro l'80,7% di chi non l'aveva. I nuovi interventi sono stati il 20,6% contro il 5,3% e l'artrosi alla radiografia era più avanzata dopo circa tre anni.", "Il limite: studio retrospettivo, senza assegnazione casuale; mostra un'associazione e non dice se la frattura causi l'esito. Il tipo di sutura non è riportato.\nFonte: PubMed, PMID 42958723."], "pazienti": ["Il menisco interno può staccarsi dalla sua radice posteriore e in alcuni casi si ricuce. Uno studio su 91 persone ha guardato se una piccola frattura dell'osso sotto la cartilagine, vista alla risonanza, cambia il risultato.", "Chi aveva quella frattura ha avuto più spesso un miglioramento limitato e più spesso una nuova operazione, e la sua artrosi alla radiografia era più avanzata dopo circa tre anni.", "Lo studio guarda indietro nel tempo e non può dire che la frattura sia la causa. Per ogni caso decide il chirurgo con il paziente.\nFonte: PubMed, PMID 42958723."]}, "linkedin": {"chir": ["Radice mediale e SIFK (Arthroscopy, 2026): coorte retrospettiva, 91 pazienti operati di sutura della radice posteriore, follow-up medio 38,3 mesi; 34 (37,4%) con frattura da insufficienza subcondrale alla RM.", "Con SIFK: KOOS-JR raggiunge la differenza minima rilevante nel 38,2% contro l'80,7% (p < 0,001); reinterventi 20,6% contro 5,3% (differenza di rischio 15,3 punti, IC 95% 1,6-31,9); Kellgren-Lawrence mediano 3,0 contro 2,0 (p = 0,013).", "Il limite: retrospettivo, reinterventi in pochi pazienti (7 e 3, dedotti dalle percentuali), tecnica di sutura e centralizzazione non riportate. Solo abstract.\nFonte: PubMed, PMID 42958723."], "misto": ["Sutura della radice del menisco interno: conta la frattura da insufficienza dell'osso sotto la cartilagine? In una coorte retrospettiva di 91 pazienti, 34 l'avevano alla risonanza prima dell'intervento.", "Con la frattura il miglioramento clinicamente importante si è visto nel 38,2% contro l'80,7% (p < 0,001) e i nuovi interventi nel 20,6% contro il 5,3% (differenza di rischio 15,3 punti, IC 95% 1,6-31,9).", "Il limite: studio retrospettivo che mostra un'associazione; pochi nuovi interventi, tecnica di sutura non riportata. Solo abstract.\nFonte: PubMed, PMID 42958723."], "pazienti": ["Una ricerca su 91 persone operate al menisco interno, nella parte che lo ancora all'osso, ha guardato il ruolo di una piccola frattura dell'osso sotto la cartilagine.", "Chi la aveva prima dell'intervento ha avuto più spesso un miglioramento limitato e più spesso un nuovo intervento nei tre anni successivi.", "Lo studio guarda indietro nel tempo e non dimostra la causa; ogni caso si valuta con il chirurgo.\nFonte: PubMed, PMID 42958723."]}, "instagram": {"chir": ["Radice del menisco mediale: la SIFK preoperatoria pesa sull'esito della sutura.", "91 pazienti: reinterventi 20,6% contro 5,3%, KOOS-JR rilevante 38,2% contro 80,7%.", "Retrospettivo; tecnica non riportata.\nFonte: PubMed, PMID 42958723."], "misto": ["Menisco interno ricucito alla radice: conta una piccola frattura dell'osso sotto la cartilagine.", "In 91 pazienti chi l'aveva ha avuto più nuovi interventi e meno miglioramento.", "Studio retrospettivo, mostra un'associazione.\nFonte: PubMed, PMID 42958723."], "pazienti": ["Menisco ricucito alla radice: una piccola frattura dell'osso può cambiare il risultato.", "In uno studio su 91 persone, chi l'aveva ha avuto più spesso un nuovo intervento.", "Studio retrospettivo, non prova la causa.\nFonte: PubMed, PMID 42958723."]}, "reel": {"chir": ["Radice meniscale e SIFK.", "Con SIFK: reinterventi 20,6% contro 5,3%.", "Retrospettivo; 91 pazienti.\nFonte: PubMed, PMID 42958723."], "misto": ["Menisco: ricucire la radice.", "Con una piccola frattura dell'osso, più nuovi interventi.", "Studio retrospettivo.\nFonte: PubMed, PMID 42958723."], "pazienti": ["Menisco ricucito alla radice.", "Una frattura dell'osso sotto la cartilagine pesa sul risultato.", "Studio che guarda indietro.\nFonte: PubMed, PMID 42958723."]}}};
var TAGS={"2": {"linkedin": "#Ortopedia #Menisco #Ginocchio", "instagram": "#ortopedia #ginocchio #menisco #radicemeniscale #chirurgiadelginocchio #artroscopia #medicinabasatasulleprove #ortopediaticino #ticino #salute", "kw": "menisco interno, radice del menisco, sutura del menisco, frattura da insufficienza subcondrale, chirurgia del ginocchio, ginocchio, ortopedia"}};
var NLB={"1": {"prof": ["Slope di 12° o più: per l'editoriale il LET può non bastare a proteggere il crociato", "Editoriale su Arthroscopy (2026; solo abstract): con slope tibiale posteriore di 12° o più e traslazione tibiale anteriore statica oltre 5 mm l'autore scrive che né l'innesto rotuleo né l'aggiunta di una tenodesi laterale possono bastare a proteggere l'innesto del crociato, e che l'osteotomia di chiusura anteriore va considerata.", "Nota critica: è un'opinione senza dati propri né numerosità; l'autore stesso scrive che servono prove per dire se l'osteotomia riduca il fallimento."], "mix": ["Crociato e tibia molto inclinata: il solo rinforzo laterale può non bastare", "Un commento pubblicato su Arthroscopy (2026) riguarda i pazienti con la tibia molto inclinata all'indietro, 12 gradi o più, e che scivola in avanti di oltre 5 millimetri. L'autore scrive che né il tendine rotuleo né il rinforzo sul lato esterno possono bastare a proteggere il nuovo legamento e che in questi casi si può considerare di correggere l'inclinazione con un'osteotomia.", "Nota sul limite: è un parere e non uno studio con pazienti; lo stesso autore scrive che servono ulteriori prove."], "paz": ["Crociato: con la tibia molto inclinata la sola ricostruzione può non bastare", "Un commento pubblicato su una rivista di chirurgia artroscopica riguarda i pazienti con la tibia molto inclinata all'indietro. L'autore scrive che in questi casi può non bastare ricostruire il legamento e rinforzare il lato esterno, e che si può valutare di correggere anche l'inclinazione dell'osso.", "Nota rassicurante: è un parere e non uno studio, e lo stesso autore dice che servono altre ricerche; il chirurgo valuta ogni caso con misure precise."], "kw": "legamento crociato anteriore, pendenza della tibia, osteotomia, chirurgia del ginocchio"}, "2": {"prof": ["Radice meniscale suturata: con frattura subcondrale più reinterventi e più artrosi", "Coorte retrospettiva (Arthroscopy, 2026; solo abstract): 91 pazienti con sutura della radice posteriore mediale e almeno 2 anni di follow-up. Con frattura subcondrale da insufficienza alla RM (34 pazienti) il KOOS-JR raggiunge la differenza minima rilevante nel 38,2% contro l'80,7% (p < 0,001); reinterventi 20,6% (IC 95% 8,7-37,9) contro 5,3% (IC 95% 1,1-14,6).", "Nota critica: retrospettivo e non randomizzato, reinterventi in pochi pazienti (7 contro 3, dedotti dalle percentuali), tecnica di sutura non riportata."], "mix": ["Radice del menisco ricucita: una frattura dell'osso sotto la cartilagine pesa sul risultato", "In una coorte retrospettiva di 91 pazienti operati alla radice posteriore del menisco interno, 34 avevano già alla risonanza una piccola frattura da insufficienza dell'osso sotto la cartilagine. In questi pazienti un miglioramento clinicamente importante si è visto nel 38,2% contro l'80,7% e un nuovo intervento nel 20,6% contro il 5,3%, a oltre due anni.", "Nota sul limite: studio retrospettivo che mostra un'associazione e non una causa; pochi nuovi interventi e tecnica di sutura non riportata."], "paz": ["Menisco ricucito alla radice: una piccola frattura dell'osso può cambiare il risultato", "Uno studio su 91 persone operate per ricucire il menisco interno alla sua radice ha guardato chi aveva già, prima dell'intervento, una piccola frattura dell'osso sotto la cartilagine. Questi pazienti hanno avuto più spesso un miglioramento limitato e un nuovo intervento, e dopo circa tre anni l'artrosi alla radiografia era più avanzata.", "Nota rassicurante: lo studio guarda indietro nel tempo e non dimostra la causa; la valutazione resta del chirurgo, caso per caso."], "kw": "menisco interno, radice del menisco, sutura del menisco, frattura da insufficienza, ginocchio"}, "3": {"prof": ["Lemaire modificato con ancora knotless a tutta sutura: nota tecnica con fissazione onlay", "Nota tecnica con video (Arthroscopy Techniques, 2026; testo completo letto): banda ileotibiale che resta attaccata a Gerdy, passata in profondità al collaterale laterale e fissata in onlay con un'ancora da 1,8 mm dopo la ricostruzione del crociato, a circa 20° di flessione.", "Nota critica: nessun paziente e nessun esito, i vantaggi sono un giudizio degli autori; un autore dichiara consulenze per Smith & Nephew, produttore dell'ancora."], "mix": ["Rinforzo laterale dopo il crociato: descritta una tecnica con una piccola ancora senza nodi", "Una nota tecnica descrive come aggiungere alla ricostruzione del crociato un rinforzo sul lato esterno del ginocchio usando una striscia della fascia della coscia, fissata all'osso con una piccola ancora senza nodi. È la tecnica detta Lemaire modificata.", "Nota sul limite: è la descrizione di un gesto chirurgico, senza pazienti né risultati; i vantaggi indicati sono un giudizio degli autori."], "paz": ["Crociato: una tecnica per rinforzare il lato esterno del ginocchio con una piccola ancora", "Una nota tecnica descrive come, durante l'operazione al crociato, si possa rinforzare il lato esterno del ginocchio con una striscia di tessuto della stessa gamba, fissata all'osso con una piccola ancora senza nodi.", "Nota rassicurante: è una descrizione per chirurghi e non uno studio sui pazienti; la scelta della tecnica spetta al chirurgo, caso per caso."], "kw": "legamento crociato anteriore, rinforzo laterale, Lemaire, chirurgia del ginocchio"}, "4": {"prof": ["LCA all-inside con hamstring: per l'editoriale il problema è l'innesto, non il costrutto", "Editoriale su Arthroscopy (2026; solo abstract) sui fallimenti elevati riportati a lungo termine dopo LCA all-inside con hamstring: allungamento dell'innesto e del loop regolabile sono ipotesi, ma gli autori indicano come spiegazione più semplice l'innesto hamstring stesso, meno tollerante nei pazienti ad alto rischio, e il quadricipite o il rotuleo come alternativa.", "Nota critica: è un'opinione senza dati propri; l'abstract non riporta numeri né nomina il retto femorale o il LET."], "mix": ["Crociato con i tendini della coscia: un commento attribuisce i fallimenti al tipo di tendine", "Un commento pubblicato su Arthroscopy (2026) discute i fallimenti riportati, a lungo termine, dopo la ricostruzione del crociato con i tendini della parte posteriore della coscia e una tecnica che lavora tutta dentro l'articolazione. Gli autori scrivono che la spiegazione più semplice è il tipo di tendine, meno tollerante nei pazienti ad alto rischio, e indicano per questi il tendine del quadricipite o quello rotuleo.", "Nota sul limite: è un parere senza dati propri e non uno studio; l'abstract non riporta numeri."], "paz": ["Crociato: un commento sul tipo di tendine nei pazienti più esposti a una nuova rottura", "Un commento su una rivista di chirurgia artroscopica discute perché, in alcuni studi, i tendini della coscia usati per ricostruire il crociato cedano più spesso a lungo termine. Gli autori suggeriscono che conti soprattutto il tipo di tendine e indicano altre scelte per i pazienti più a rischio.", "Nota rassicurante: è un parere e non uno studio, e la scelta dell'innesto si decide con il chirurgo in base al singolo paziente."], "kw": "legamento crociato anteriore, innesto, tendini della coscia, chirurgia del ginocchio"}, "5": {"prof": ["Radice mediale: l'asimmetria fra slope mediale e laterale si associa alla lesione", "Studio retrospettivo multicentrico (Knee Surgery & Related Research, 2026; solo abstract): 120 ginocchia di pazienti di 50-75 anni, 26 con lesione della radice posteriore mediale. La differenza fra slope mediale e laterale è associata alla lesione, OR 2,17 per grado (IC 95% 1,56-3,02), AUC 0,87 (IC 95% 0,79-0,95); soglia esplorativa 4,0°.", "Nota critica: associazione trasversale con 26 lesioni, soglia ricavata dagli stessi dati e senza validazione esterna."], "mix": ["Menisco interno: nella lesione della radice la tibia ha un'inclinazione diversa fra i due lati", "Uno studio su 120 ginocchia di persone fra 50 e 75 anni ha misurato alla risonanza l'inclinazione all'indietro del piatto tibiale, lo slope, sul lato interno e su quello esterno. Nelle 26 ginocchia con lesione della radice del menisco interno la differenza fra i due lati era maggiore (OR 2,17 per grado; IC 95% 1,56-3,02).", "Nota sul limite: è un'associazione, non dice che la differenza causi la lesione né che correggerla la prevenga; i casi sono pochi."], "paz": ["Menisco: nelle ginocchia con lesione alla radice la tibia ha un'inclinazione diversa", "Uno studio su 120 persone ha misurato alla risonanza l'inclinazione del piatto della tibia sul lato interno e su quello esterno. In chi aveva una lesione alla radice del menisco interno la differenza fra i due lati era più marcata.", "Nota rassicurante: lo studio osserva un'associazione e non dice che l'inclinazione sia la causa; la valutazione resta del chirurgo, caso per caso."], "kw": "menisco interno, radice del menisco, pendenza della tibia, ginocchio"}, "6": {"prof": ["Osteotomia tibiale alta aperta: apertura anteromediale e slope, errori sui tre piani alla TC", "Studio TC retrospettivo (Arthroscopy, 2026; solo abstract) su 110 ginocchia: errore medio dell'angolo di apertura -0,1°, aumento medio dello slope 2,6° e rotazione interna 2,7°. Ogni grado di rotazione interna si associa a 1,6 punti di Lysholm in meno a un anno (p = 0,018); fratture della cerniera laterale nel 23,6%.", "Nota critica: retrospettivo, senza confronto con altre tecniche; deviazioni standard e intervalli non riportati nell'abstract."], "mix": ["Osteotomia della tibia: la correzione si sposta anche in inclinazione e rotazione", "Uno studio con la TC su 110 ginocchia operate di osteotomia tibiale alta aperta ha misurato di quanto la correzione si discosti dal piano su tre dimensioni. In media l'inclinazione all'indietro della tibia, lo slope, è aumentata di 2,6° e la tibia si è ruotata all'interno di 2,7°; ogni grado di rotazione si associa a 1,6 punti di punteggio Lysholm in meno a un anno.", "Nota sul limite: studio retrospettivo senza confronto con altre tecniche, quindi mostra associazioni; il punteggio perso per grado è piccolo."], "paz": ["Osteotomia della tibia: alla TC la correzione si sposta un poco anche in rotazione", "Uno studio su 110 ginocchia operate di osteotomia ha misurato con la TC di quanti gradi la tibia si sia spostata dalla correzione prevista, in inclinazione e in rotazione: in media pochi gradi. Una rotazione maggiore si è associata a un punteggio funzionale appena più basso a un anno.", "Nota rassicurante: sono differenze piccole, misurate guardando indietro nel tempo; ogni caso si pianifica con il chirurgo."], "kw": "osteotomia tibiale, ginocchio varo, slope tibiale, chirurgia del ginocchio"}, "7": {"prof": ["LCA con residuo conservato e sutura del moncone: meno allargamento del tunnel tibiale a un anno", "RCT su 179 pazienti (J Exp Orthop, 2026; solo abstract): allargamento del tunnel tibiale alla TC 14,58 ± 4,49% contro 19,74 ± 4,36% (p < 0,001); allargamento oltre il 20% nell'11,4% contro il 25,3% (RR 0,45; IC 95% 0,23-0,89, calcolo mio). Tunnel femorale e posizione dei tunnel invariati.", "Nota critica: esito di imaging e non clinico, registrazione retrospettiva, innesto e LET non riportati."], "mix": ["Crociato: conservare il residuo del legamento riduce l'allargamento del tunnel nell'osso", "Uno studio randomizzato su 179 pazienti ha confrontato la ricostruzione del crociato conservando e cucendo il moncone del legamento con la sua asportazione. A un anno, alla TC, il tunnel nella tibia si era allargato meno (14,6% contro 19,7%; p < 0,001) e in meno pazienti oltre il 20% (11,4% contro 25,3%).", "Nota sul limite: si misura un'immagine e non come stanno i pazienti; lo studio non dice se questo cambi stabilità o punteggi."], "paz": ["Crociato: cucire il residuo del legamento riduce l'allargamento del tunnel nella tibia", "Uno studio su 179 persone operate di crociato ha confrontato due modi di lavorare: lasciare e cucire ciò che resta del legamento rotto oppure asportarlo. A un anno la TC mostra che il tunnel scavato nell'osso della tibia si è allargato un po' meno nel primo gruppo.", "Nota rassicurante: lo studio misura un'immagine e non dice che i pazienti stiano diversamente; la scelta della tecnica spetta al chirurgo."], "kw": "legamento crociato anteriore, tunnel tibiale, ricostruzione del crociato, chirurgia del ginocchio"}};
var ARTICLES=[{n:1,mono:'m-gray',dot:'orange',sec:'res',j:'Arthroscopy',h:'Slope di 12° o più: il LET può non bastare a proteggere il crociato',v:'Commento editoriale (un\'opinione, non uno studio) sulla protezione dell\'innesto dopo LCA primaria in ginocchia con slope tibiale posteriore di 12° o più e traslazione tibiale anteriore statica oltre 5 mm: l\'autore scrive che né l\'innesto rotuleo né l\'aggiunta di un LET possono bastare e che l\'osteotomia di chiusura anteriore va considerata. Aggiunge che servono prove per dire se riduca davvero il fallimento.',ax:'Choi',date:'ott 2026',meta:'editoriale, nessun dato proprio, solo abstract',pmid:'42949191',doi:'10.1002/arj.70722',journal:'Arthroscopy',authors:'Choi NH',design:'Editorial Commentary su Arthroscopy (Choi; Eulji Medical Center, Seul). Opinione di un autore su un tema; l\'abstract non indica quale studio commenti né riporta pazienti. Solo abstract: non è in PMC.',pop:'Nessuna: l\'abstract non riporta pazienti. Situazione discussa: LCA primaria con slope tibiale posteriore di 12° o più e traslazione tibiale anteriore statica oltre 5 mm.',results:'Nessun dato originale. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'L\'autore: con slope di 12° o più, l\'osteotomia di chiusura anteriore associata alla ricostruzione va considerata per proteggere l\'innesto; servono prove per dire se riduca il fallimento.',limits:'Editoriale: opinione, non dati · L\'abstract non cita lo studio commentato né la sua numerosità · Il tendine quadricipitale e il retto femorale non sono nominati: non sappiamo se il giudizio valga per il tuo innesto',perte:'Arancione: tocca la tua scelta di fare il LET su tutti. Per l\'autore, con slope di 12° o più il LET da solo può non proteggere l\'innesto. Non è un dato, è un\'opinione, e l\'abstract non dice su quale innesto. Per te conta come promemoria: fai già osteotomie e correzioni di slope, quindi la strada esiste. Cosa fare: nulla da cambiare; misura lo slope nel work-up del LCA e dì nel colloquio che con slope alto il LET universale potrebbe non bastare. Aggiunge una nota a T1, non la chiude.'},{n:2,mono:'m-gray',dot:'green',sec:'res',j:'Arthroscopy',h:'Sutura di radice con frattura subcondrale: meno miglioramento, più reinterventi, più artrosi',v:'Coorte retrospettiva su 91 pazienti operati di sutura della radice posteriore del menisco mediale, con follow-up medio di 38,3 mesi; 34 (37,4%) avevano alla RM una frattura da insufficienza subcondrale (SIFK), per l\'85% di grado 1 o 2. Con SIFK il miglioramento clinicamente rilevante del KOOS-JR si raggiunge nel 38,2% contro l\'80,7% (p < 0,001), i reinterventi sono il 20,6% contro il 5,3% e il grado Kellgren-Lawrence mediano è 3,0 contro 2,0.',ax:'Garcia, Cohen, Gilat, Ralls, Atkins, Murray, Jan, Dave, Cole, Yanke, Verma, Chahla',date:'ott 2026',meta:'coorte retrospettiva, 91 pazienti, livello III, solo abstract',pmid:'42958723',doi:'10.1002/arj.70712',journal:'Arthroscopy',authors:'Garcia JR, Cohen EM, Gilat R, Ralls M, Atkins MA, Murray M, Jan K, Dave U, Cole BJ, Yanke AB e altri 2',design:'Coorte retrospettiva (livello III dichiarato) su pazienti operati di riparazione di una lesione primaria isolata della radice posteriore del menisco mediale, stratificati per presenza di SIFK alla RM. Esiti: KOOS-JR, IKDC e VR-12 con soglie di cambiamento clinicamente rilevante specifiche della coorte, reinterventi, progressione radiografica dell\'artrosi. Solo abstract: non è in PMC.',pop:'91 pazienti, età media 56,5 ± 9,4 anni, 73,6% donne, BMI medio 32,5 ± 6,1; follow-up 38,3 ± 15,3 mesi (24-82), uguale nei due gruppi (p = 0,841); 34 con SIFK, 85% di grado 1 o 2. Tecnica di riparazione (transtibiale o altra) non riportata nell\'abstract.',results:'KOOS-JR, differenza minima clinicamente rilevante raggiunta: 80,7% senza SIFK contro 38,2% con SIFK (p < 0,001); stato di sintomi accettabile 61,4% contro 35,3% (p = 0,028). Reinterventi: 20,6% (IC 95% 8,7-37,9) con SIFK contro 5,3% (IC 95% 1,1-14,6) senza; differenza di rischio 15,3 punti (IC 95% 1,6-31,9; p = 0,036). Grado Kellgren-Lawrence postoperatorio mediano 3,0 (IQR 3,0-4,0) contro 2,0 (IQR 2,0-3,0) (p = 0,013); spazio articolare 2,8 ± 0,6 contro 3,8 ± 1,0 mm (p = 0,002).',concl:'Gli autori: la SIFK preoperatoria si associa a minor probabilità di miglioramento significativo, più reinterventi e peggior esito radiografico dopo la sutura della radice.',limits:'Retrospettivo e non randomizzato: la SIFK si associa agli esiti, non li causa; i gruppi erano simili al basale nei dati riportati, ma l\'abstract non mostra un\'analisi aggiustata · Reinterventi in 7 pazienti con SIFK e in 3 senza (eventi dedotti dalle percentuali): l\'intervallo della differenza è molto largo (1,6-31,9) · Tecnica di riparazione, centralizzazione e allineamento non riportati',perte:'Verde: riguarda la tua rifissazione della radice. È un lavoro sull\'indicazione più che sulla tecnica: in una coorte con BMI medio di 32,5, più di un paziente su tre aveva già una SIFK alla RM, e questi pazienti hanno avuto meno miglioramenti, più reinterventi e più artrosi dopo la sutura. L\'abstract non dice se la sutura fosse transtibiale, quindi non sappiamo se valga per la tua pull-out. Cosa fare: nel work-up della radice cerca la SIFK alla RM e dillo nel colloquio come fattore di prognosi, accanto all\'estrusione di T3; nulla da cambiare nella tecnica. Aggiunge un fattore a T3, senza chiuderla.'},{n:3,mono:'m-gray',dot:'green',sec:'res',j:'Arthrosc Tech',h:'LET con ancora knotless a tutta sutura: Lemaire modificato in onlay, nessun paziente',v:'Nota tecnica con video (Illinois) sul Lemaire modificato dopo la ricostruzione del LCA: una banda ileotibiale centrale, che resta attaccata a Gerdy, viene passata in profondità al collaterale laterale e fissata in onlay con un\'ancora knotless a tutta sutura da 1,8 mm (Q-Fix, Smith & Nephew), a 8 mm prossimali e 4 mm posteriori all\'inserzione del collaterale, a circa 20° di flessione. Nessun paziente.',ax:'Lucina, Tierney, Patel',date:'ott 2026',meta:'nota tecnica, nessun paziente, testo completo letto (PMC)',pmid:'42953463',doi:'10.1002/atn2.70345',journal:'Arthroscopy techniques',authors:'Lucina L, Tierney S, Patel RM',design:'Nota tecnica con video, case-based (Illinois Center for Orthopaedic Research and Education). Testo completo letto su PMC: tecnica passo per passo, vantaggi e svantaggi in tabella. Un autore dichiara consulenze per Smith & Nephew e Vericel.',pop:'Nessun paziente: descrizione case-based. Contesto: LCA primaria o di revisione; l\'innesto del LCA non è specificato nel testo.',results:'Nessun risultato clinico. Dettagli del costrutto: banda ileotibiale di almeno 8 cm, foro da 2 mm profondo 17,1 mm, ancora da 1,8 mm che si espande fino a 4 mm, tensionamento a circa 20° di flessione in rotazione neutra. Dimensioni dell\'effetto e intervalli di confidenza non riportati.',concl:'Gli autori: tecnica che preserva l\'osso, a basso profilo e riproducibile, senza interferenza con la fissazione femorale del LCA; il tensionamento con ancora knotless evita la lassità dei nodi.',limits:'Nessun paziente e nessun esito: i vantaggi sono un giudizio degli autori, non una misura · Un autore dichiara consulenze per Smith & Nephew, produttore dell\'ancora · Rischi citati (morbilità del prelievo ileotibiale, tempo operatorio) senza dati',perte:'Verde, con un\'annotazione prima di tutto: è un Lemaire modificato con fissazione onlay come il tuo, ma il passaggio è in profondità al collaterale laterale, mentre il tuo è superficiale (a volte profondo), e l\'ancora è un modello specifico a tutta sutura. Per T2 è un\'altra variante di costrutto descritta senza dati: non dice se onlay profondo e onlay superficiale si comportino allo stesso modo. Cosa fare: nulla da cambiare; tienila come riferimento se un collega cita il passaggio profondo con ancora knotless.'},{n:4,mono:'m-gray',dot:'green',sec:'res',j:'Arthroscopy',h:'LCA all-inside con hamstring: l\'editoriale attribuisce i fallimenti all\'innesto, non al costrutto',v:'Commento editoriale (non uno studio) sui fallimenti elevati riportati a lungo termine dopo LCA all-inside con hamstring. Gli autori elencano allungamento dell\'innesto, carico diseguale dei capi, allungamento del loop regolabile e lunghezza di lavoro della fissazione corticale, ma scrivono che la spiegazione più semplice resta l\'innesto stesso, meno tollerante nei pazienti ad alto rischio: per questi indicano il quadricipite o il rotuleo, e notano che l\'all-inside con quadricipite non mostra lo stesso segnale.',ax:'Laporte, Gilmer',date:'ott 2026',meta:'editoriale, nessun dato proprio, solo abstract',pmid:'42949164',doi:'10.1002/arj.70715',journal:'Arthroscopy',authors:'Laporte C, Gilmer BB',design:'Editorial Commentary su Arthroscopy (Mammoth Orthopedic Institute, California). Opinione di due autori su un segnale di fallimento; l\'abstract non riporta pazienti né l\'articolo commentato. Solo abstract: non è in PMC.',pop:'Nessuna: l\'abstract non riporta pazienti. Tema: LCA all-inside con autoinnesto hamstring, pazienti ad alto rischio.',results:'Nessun dato originale. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: il problema sembra l\'innesto hamstring più che il costrutto; nei pazienti ad alto rischio il quadricipite o il rotuleo restano la scelta indicata.',limits:'Editoriale: opinione, non dati; l\'abstract non cita lo studio commentato né i suoi numeri · Il quadricipite è nominato come alternativa, senza dati sul retto femorale né sul LET · Il segnale di fallimento citato non è quantificato nell\'abstract',perte:'Verde: sostiene la tua scelta di non usare l\'hamstring, ma è un\'opinione e non un dato. Gli autori scrivono che l\'all-inside con quadricipite non mostra lo stesso segnale di fallimento; non dicono nulla sul retto femorale né sul LET. Cosa fare: nulla da cambiare; è un argomento da tenere per il colloquio con chi chiede perché non usi l\'hamstring, citando che è un editoriale. Non muove T1 né T2.'},{n:5,mono:'m-gray',dot:'green',sec:'res',j:'Knee Surg Relat Res',h:'Radice mediale: la differenza fra slope mediale e laterale distingue le ginocchia con lesione',v:'Studio multicentrico retrospettivo su 120 ginocchia di pazienti di 50-75 anni, senza artrosi avanzata, sottoposti a RM per dolore: 26 (21,7%) avevano una lesione della radice posteriore del menisco mediale. Lo slope mediale era simile nei due gruppi, quello laterale minore nelle lesioni, e la differenza ΔPTS (mediale meno laterale) maggiore: OR 2,17 per grado (IC 95% 1,56-3,02), AUC 0,87 (IC 95% 0,79-0,95); soglia esplorativa 4,0° con sensibilità 80,8% e specificità 81,9%.',ax:'Harada, Mori, Abe, Aki, Kamimura, Ogasawara, Ito, Aizawa',date:'ott 2026',meta:'retrospettivo multicentrico, 120 ginocchia, solo abstract',pmid:'42958592',doi:'10.1186/s43019-026-00352-2',journal:'Knee surgery & related research',authors:'Harada K, Mori Y, Abe T, Aki T, Kamimura M, Ogasawara M, Ito K, Aizawa T',design:'Studio retrospettivo multicentrico in due istituti: slope tibiale posteriore mediale (MPTS) e laterale (LPTS), angolo prossimale mediale della tibia (MPTA) e angolo femorale distale laterale (LDFA) misurati alla RM; ΔPTS = MPTS meno LPTS. Confronto prima e dopo appaiamento 1:1 per età, sesso e BMI, poi regressione logistica multivariata e curva ROC. Livello di evidenza non dichiarato nell\'abstract. Solo abstract: non è in PMC.',pop:'120 ginocchia di pazienti di 50-75 anni sottoposti a RM per dolore al ginocchio in due istituti, con esclusione dell\'artrosi Kellgren-Lawrence 3-4; 26 (21,7%) con lesione della radice posteriore mediale; 22 coppie dopo l\'appaiamento.',results:'MPTS senza differenza fra i gruppi; LPTS minore (p < 0,001) e ΔPTS maggiore (p < 0,001) con la lesione, confermati dopo l\'appaiamento (22 coppie; ΔPTS p < 0,001). ΔPTS associato alla lesione in modo indipendente: OR 2,17 per 1° (IC 95% 1,56-3,02; p < 0,001). ROC di ΔPTS: AUC 0,87 (IC 95% 0,79-0,95), contro 0,73 per LPTS e 0,54 per MPTS (DeLong p = 0,006 e p < 0,001). Soglia esplorativa 4,0°: sensibilità 80,8%, specificità 81,9%.',concl:'Gli autori: le ginocchia con lesione della radice hanno slope laterale minore e asimmetria maggiore; un ΔPTS di 4,0° o più può servire da soglia esplorativa, e l\'asimmetria dello slope può essere un fattore morfologico associato.',limits:'Trasversale e retrospettivo: associa lo slope alla lesione, non dice che la causi né che correggerlo la prevenga · Solo 26 lesioni e 22 coppie appaiate: l\'IC dell\'OR è largo e la soglia di 4,0° è ricavata dagli stessi dati, senza validazione esterna · Coorte di 50-75 anni senza artrosi avanzata: non vale per lesioni acute o per pazienti più giovani',perte:'Verde: tocca insieme due cose che fai, la radice transtibiale e la correzione di slope. Il dato nuovo è che conta l\'asimmetria fra slope mediale e laterale più dello slope mediale da solo, il parametro finora guardato; è un\'associazione trasversale con una soglia da validare. Cosa fare: quando misuri lo slope per un\'osteotomia o per il LCA, misura anche il laterale e annota la differenza nelle ginocchia con lesione di radice; nulla da cambiare nella sutura. Aggiunge un fattore anatomico a T3, senza muoverla.'},{n:6,mono:'m-gray',dot:'green',sec:'res',j:'Arthroscopy',h:'Osteotomia tibiale aperta: apertura anteromediale e sufficienza dell\'osteotomia spostano slope e rotazione',v:'Studio TC retrospettivo su 110 ginocchia (94 pazienti) operate di osteotomia tibiale alta aperta biplanare: errore medio dell\'angolo di apertura -0,1°, aumento medio dello slope di 2,6° e rotazione interna di 2,7°. Ogni grado di rotazione interna si associa a 1,6 punti di Lysholm in meno a un anno (p = 0,018); fratture della cerniera laterale nel 23,6%.',ax:'Morita, Kuriyama, Yamawaki, Nishitani, Nakamura, Ito, Matsuda',date:'ott 2026',meta:'retrospettivo, 110 ginocchia, livello III, solo abstract',pmid:'42952223',doi:'10.1002/arj.70697',journal:'Arthroscopy',authors:'Morita Y, Kuriyama S, Yamawaki Y, Nishitani K, Nakamura S, Ito H, Matsuda S',design:'Studio retrospettivo caso-controllo (livello III dichiarato) su osteotomie tibiali alte aperte biplanari eseguite fra settembre 2014 e ottobre 2022: errore dell\'angolo di apertura, variazione dello slope e rotazione assiale misurati su TC prima e a 1-2 settimane dall\'intervento, con angolo della cerniera e sufficienza dell\'osteotomia; modelli a effetti misti corretti per età, sesso e BMI. Solo abstract: non è in PMC.',pop:'110 ginocchia in 94 pazienti. Età, sesso e BMI non riportati nell\'abstract; esito clinico con Lysholm a un anno.',results:'Errore medio dell\'angolo di apertura -0,1°, aumento medio dello slope 2,6°, rotazione interna 2,7° (deviazioni standard non riportate nell\'abstract). Angolo di apertura pianificato associato a sottocorrezione coronale (β = 0,230; p = 0,001) e rotazione interna (β = 0,321; p = 0,001); angolo della cerniera a sottocorrezione (β = 0,023; p = 0,039) e aumento dello slope (β = 0,045; p = 0,044); sufficienza dell\'osteotomia a minor aumento dello slope (β = -0,039; p = 0,005) ma maggiore rotazione interna (β = 0,046; p < 0,001). Ogni grado di rotazione interna: Lysholm a un anno -1,572 punti (p = 0,018). Fratture della cerniera laterale 23,6%.',concl:'Gli autori: l\'apertura anteromediale si associa a sottocorrezione coronale e aumento dello slope; una osteotomia più sufficiente riduce l\'aumento dello slope ma aumenta la rotazione interna della tibia distale, associata a Lysholm più bassi a un anno.',limits:'Retrospettivo, senza confronto con altre tecniche: mostra associazioni, non dice quale gesto riduca l\'errore · Correzione solo per età, sesso e BMI; l\'effetto sul Lysholm (circa 1,6 punti per grado) è piccolo e senza intervallo nell\'abstract · TC a 1-2 settimane: non dice se l\'errore persista né l\'esito a lungo termine',perte:'Verde: riguarda l\'osteotomia e il controllo dello slope, che fai. Il dato utile è che in un\'osteotomia aperta lo slope sale in media di 2,6° anche con l\'angolo di apertura centrato, e che una osteotomia più sufficiente frena lo slope ma ruota di più la tibia distale. Cosa fare: se correggi in apertura un varo con LCA instabile o con slope già alto, pianifica l\'aumento atteso dello slope e controlla la rotazione alla TC postoperatoria; il lavoro non dice come ridurla. Nulla da cambiare nella tecnica.'},{n:7,mono:'m-gray',dot:'green',sec:'res',j:'J Exp Orthop',h:'Crociato con residuo conservato e sutura del moncone: meno allargamento del tunnel tibiale a un anno',v:'RCT prospettico su 179 pazienti operati di LCA primaria (88 con residuo conservato e sutura del moncone tibiale, 91 con resezione del moncone). A un anno, alla TC, l\'allargamento del tunnel tibiale è 14,58 ± 4,49% contro 19,74 ± 4,36% (p < 0,001); allargamento oltre il 20% nell\'11,4% contro il 25,3% (RR 0,45; p = 0,016). Tunnel femorale e posizione dei tunnel invariati.',ax:'El-Desouky, Elkalyoby, Rashwan, Gaballah, Abdelrazek',date:'ott 2026',meta:'RCT, 179 pazienti, livello I dichiarato, esito su TC, solo abstract',pmid:'42953369',doi:'10.1002/jeo2.70962',journal:'Journal of experimental orthopaedics',authors:'El-Desouky M, Elkalyoby AS, Rashwan AS, Gaballah AI, Abdelrazek BH',design:'RCT prospettico (livello I dichiarato), registrato retrospettivamente su ClinicalTrials.gov (NCT07236593, registrazione del 15 novembre 2025): residuo conservato con sutura del moncone tibiale contro resezione del moncone; TC tridimensionale a 2 settimane e a 1 anno, allargamento dei tunnel in percentuale e posizione col metodo del quadrante. Solo abstract: il testo è in PMC ma non è stato letto.',pop:'179 pazienti con LCA primaria: 88 con residuo conservato, 91 con resezione; diametri basali dei tunnel comparabili. Età, sesso, innesto e fissazione non riportati nell\'abstract.',results:'Allargamento del tunnel tibiale a 1 anno 14,58 ± 4,49% contro 19,74 ± 4,36% (p < 0,001). Allargamento oltre il 20%: 11,4% contro 25,3% (RR 0,45, p = 0,016; IC 95% 0,23-0,89, calcolo mio con potenza.py su 10/88 contro 23/91). Tunnel femorale 18,23 ± 2,92% contro 18,35 ± 2,59% (p = 0,766). Posizione dei tunnel senza differenze rilevanti. Esiti clinici non riportati nell\'abstract.',concl:'Gli autori: la conservazione del residuo con sutura del moncone riduce selettivamente l\'allargamento del tunnel tibiale a 12 mesi senza peggiorare la posizione dei tunnel, e va considerata quando conta l\'integrità del tunnel tibiale.',limits:'Esito di imaging e non clinico: l\'abstract non riporta stabilità, punteggi o re-rotture · Registrazione retrospettiva (novembre 2025) e follow-up di un anno · Innesto, LET e fissazione non riportati: non sappiamo se valga per il quadricipite',perte:'Verde: è un RCT sul LCA, ma l\'esito è un\'immagine. L\'allargamento del tunnel conta soprattutto in vista di una revisione; l\'abstract non dice quale innesto né se vi fosse il LET, quindi non sappiamo se valga per il tuo quadricipite. Cosa fare: nulla da cambiare; il conservare il residuo diventa un gesto da valutare solo se un dato clinico lo sosterrà, e qui non c\'è. Non muove T1 né T2.'}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Sabato trentuno ottobre. Oggi sette lavori, nessuna scheda rossa e una arancione. Nessun richiamo di dispositivi nuovo, nessuna linea guida o consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi. La scheda arancione è un editoriale su Arthroscopy, quindi un'opinione senza dati: con uno slope tibiale posteriore di dodici gradi o più e una traslazione tibiale anteriore statica oltre cinque millimetri, l'autore scrive che né l'innesto rotuleo né il rinforzo laterale possono bastare a proteggere l'innesto e che va considerata l'osteotomia di chiusura anteriore. Tocca il tuo LET su tutti, ma non è un dato e non nomina il quadricipite. Il lavoro del giorno è una coorte retrospettiva su Arthroscopy sulla sutura della radice del menisco mediale: novantuno pazienti, follow-up medio trentotto mesi, trentaquattro con una frattura da insufficienza subcondrale alla risonanza. Con la frattura il miglioramento clinicamente rilevante del KOOS arriva al trentotto virgola due per cento contro l'ottanta virgola sette, con p minore di zero virgola zero zero uno; i reinterventi sono il venti virgola sei per cento contro il cinque virgola tre, con differenza di rischio di quindici virgola tre punti e intervallo di confidenza dall'uno virgola sei al trentuno virgola nove; il grado di artrosi mediano è tre contro due. Il limite: retrospettivo, reinterventi in pochi pazienti, e l'abstract non dice se la sutura fosse transtibiale. Ho letto solo l'abstract. Poi una nota tecnica con video sul Lemaire modificato con ancora a tutta sutura: banda ileotibiale passata in profondità al collaterale laterale e fissata in onlay; il tuo passaggio è superficiale, e non ci sono pazienti. Un secondo editoriale, di Laporte e Gilmer, attribuisce i fallimenti elevati dell'all-inside con hamstring all'innesto più che al costrutto e indica quadricipite o rotuleo per i pazienti ad alto rischio: sostiene la tua scelta, ma è un'opinione. Sul menisco, centoventi ginocchia: la differenza fra slope mediale e laterale distingue le ginocchia con lesione di radice, odds ratio due virgola diciassette per grado con intervallo di confidenza da uno virgola cinquantasei a tre; è un'associazione trasversale. Sull'osteotomia tibiale alta aperta, centodieci ginocchia alla TC: lo slope sale in media di due virgola sei gradi e la tibia ruota all'interno di due virgola sette gradi, con un punto sei di Lysholm in meno per ogni grado di rotazione. Infine un RCT su centosettantanove pazienti: conservare il residuo del crociato e suturare il moncone riduce l'allargamento del tunnel tibiale a un anno, dal diciannove virgola sette al quattordici virgola sei per cento; è un esito di immagine, non clinico. Tensioni: la sutura di radice ha un fattore prognostico in più, la frattura subcondrale; nessuna si chiude oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Sabato trentuno ottobre. Oggi sette lavori, nessuna scheda rossa e una arancione."}, {"chi": "B", "t": "Richiami, consensus, ritrattazioni?"}, {"chi": "A", "t": "Nessun richiamo nuovo, nessuna linea guida nuova sulla tua pratica e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Allora l'arancione."}, {"chi": "A", "t": "Un editoriale su Arthroscopy, quindi un'opinione senza dati: con uno slope tibiale di dodici gradi o più e la tibia che scivola in avanti oltre cinque millimetri, l'autore scrive che né il rotuleo né il rinforzo laterale possono bastare a proteggere l'innesto, e che va considerata l'osteotomia."}, {"chi": "B", "t": "Tocca il mio LET su tutti. Ci sono dati?"}, {"chi": "A", "t": "No, e non nomina il quadricipite. È una nota in più, non cambia la tua posizione."}, {"chi": "B", "t": "Il lavoro del giorno?"}, {"chi": "A", "t": "Una coorte retrospettiva sulla sutura della radice del menisco mediale: novantuno pazienti, trentaquattro con una frattura da insufficienza subcondrale alla risonanza. Con la frattura il miglioramento clinicamente rilevante arriva al trentotto virgola due per cento contro l'ottanta virgola sette, e i reinterventi al venti virgola sei contro il cinque virgola tre."}, {"chi": "B", "t": "Quindi nel work-up della mia radice devo cercarla."}, {"chi": "A", "t": "Sì, e dirlo nel colloquio come fattore di prognosi. Il limite: è retrospettivo, i reinterventi sono pochi, e l'abstract non dice se la sutura fosse transtibiale. Ho letto solo l'abstract."}, {"chi": "B", "t": "Altro sulla mia pratica?"}, {"chi": "A", "t": "Una nota tecnica sul Lemaire modificato con ancora a tutta sutura: fissazione onlay come la tua, ma passaggio profondo al collaterale, e nessun paziente. Poi un editoriale che attribuisce i fallimenti dell'all-inside con hamstring all'innesto più che al costrutto: sostiene la tua scelta, ma è un'opinione."}, {"chi": "B", "t": "E sul menisco e sull'osteotomia?"}, {"chi": "A", "t": "Su centoventi ginocchia la differenza fra slope mediale e laterale distingue quelle con lesione di radice: associazione trasversale. Sull'osteotomia tibiale aperta, alla TC lo slope sale in media di due virgola sei gradi. Infine un RCT: conservare il residuo del crociato riduce l'allargamento del tunnel tibiale, ma è un esito di immagine."}, {"chi": "B", "t": "Tensioni?"}, {"chi": "A", "t": "Quella sulla radice guadagna un fattore prognostico; nessuna si chiude oggi."}];
